from .money import MAX_CENTS, format_amount, from_cents, to_cents


def make_invoice(amounts):
    if type(amounts) is not list:
        raise ValueError("amounts must be a list")
    items = list(amounts)  # shallow snapshot; the caller's list is not modified
    total_cents = 0
    for item in items:
        total_cents += to_cents(item)  # exact integer cents, no rounding
    if total_cents > MAX_CENTS:
        raise ValueError("total exceeds 1000000.00")
    return {"total": format_amount(from_cents(total_cents)), "count": len(items)}

